import os
import time
import cv2

root = '/root'
extensions = {'.bmp', '.jpeg', '.jpg', '.png', '.tif', '.tiff', '.webp'}
frame_index = 0
for directory, subdirectories, filenames in os.walk(root):
    subdirectories.sort()
    for filename in sorted(filenames):
        if os.path.splitext(filename)[1].lower() not in extensions:
            continue
        source_path = os.path.join(directory, filename)
        frame = cv2.imread(source_path, cv2.IMREAD_COLOR)
        if frame is None:
            raise ValueError(f'Cannot decode image: {source_path}')
        source = {'frame_index': frame_index, 'source_path': source_path, 'captured_at_unix_s': time.time()}
        emit(p01o_frame=frame, p01o_source=source)
        frame_index += 1
